// launch-factory: 서버 계측(posthog-node). 웹훅·서버 액션에서 나는 이벤트(예: checkout_complete)를 보낸다.
// 서버는 방문자의 동의를 모른다 — 부르는 쪽이 저장해 둔 결정을 forRequest 에 넘긴다. analytics 가 true 가 아니면 보내지도 쌓지도 않는다.
// distinctId 는 제품 내부 사용자 id 다(이메일 금지 — 어댑터가 거절한다).
// 분석은 선택이다(LFOBS·LFOBS2): live 에서 POSTHOG_HOST 나 POSTHOG_PROJECT_KEY 가 없으면 분석이 꺼진 것이다 — 이 함수는 던지지 않고, 아무것도 보내지 않는 같은 모양의 계측(enabled false)을 돌려준다.
// mock 도 마찬가지다(공급자에 보내지 않는다). 켜졌는지는 analytics().enabled 로 본다.
import { createServerAnalytics, disabledServerAnalytics, type DisabledServerAnalytics, type ServerAnalytics } from "@launch-factory/analytics-posthog/server"
import { env, optional } from "@/lib/launch/env"

let cached: ServerAnalytics | DisabledServerAnalytics | undefined

export function analytics(): ServerAnalytics | DisabledServerAnalytics {
  if (cached) return cached
  const host = optional("POSTHOG_HOST")
  const projectKey = optional("POSTHOG_PROJECT_KEY")
  return (cached = env().LF_MODE === "live" && host && projectKey ? createServerAnalytics({ projectKey, host }) : disabledServerAnalytics())
}

"use client"
// launch-factory: 브라우저 계측. 동의가 먼저다 — 동의 전(unset)·거부에서는 posthog-js 를 불러오지도 init 하지도 않고, 아무것도 보내지 않는다.
// projectKey 는 공개 프로젝트 키(phc_…)다. 서버 컴포넌트(레이아웃)가 POSTHOG_PROJECT_KEY·POSTHOG_HOST 를 읽어 props 로 넘긴다.
import { createContext, useContext, useMemo, type ReactNode } from "react"
import { createPostHogAnalytics, type PostHogAnalytics, type PostHogClientOptions } from "@launch-factory/analytics-posthog"

const AnalyticsContext = createContext<PostHogAnalytics | null>(null)

export function AnalyticsProvider({ children, ...options }: PostHogClientOptions & { children: ReactNode }) {
  // 옵션은 첫 렌더 값으로 한 번만 만든다(동의 저장은 onConsentChange 로)
  const analytics = useMemo(() => createPostHogAnalytics(options), [])
  return <AnalyticsContext.Provider value={analytics}>{children}</AnalyticsContext.Provider>
}

/** 블록에 넘기는 AnalyticsPort. Provider 밖에서 부르면 던진다 */
export function useAnalytics(): PostHogAnalytics {
  const analytics = useContext(AnalyticsContext)
  if (!analytics) throw new Error("useAnalytics must be used inside <AnalyticsProvider>")
  return analytics
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}
